/**
 * @name ServList
 * @author WeConnected
 * @version 5.0.0
 * @description Adds a Serv List button that opens a full-page grid of your servers and folders. Drag and drop to organize, create folders, and move servers in and out of them.
 */

const SETTINGS_KEY = "settings";
const OPEN_KEY = "openFolders";
const ORDER_KEY = "order";
const BACKUP_KEY = "backup";
const LAYOUT_KEY = "layoutV4";
const HIDDEN_KEY = "hidden";
const LOGO = "data:image/png;base64,";
const MASCOT = "data:image/png;base64,";
const BG = "data:image/jpeg;base64,";


/* ---------------------- minimal protobuf helpers (Discord settings) ---------------------- */

const b64ToBytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
const bytesToB64 = (arr) => { let str = ""; for (const b of arr) str += String.fromCharCode(b); return btoa(str); };

function readVarint(buf, pos) {
    let result = 0n, shift = 0n;
    for (;;) {
        const b = buf[pos++];
        if (b === undefined) throw new Error("protobuf: truncated varint");
        result |= BigInt(b & 0x7f) << shift;
        if (!(b & 0x80)) return [result, pos];
        shift += 7n;
        if (shift > 70n) throw new Error("protobuf: varint too long");
    }
}

function writeVarint(out, value) {
    let v = BigInt(value);
    while (v >= 0x80n) { out.push(Number(v & 0x7fn) | 0x80); v >>= 7n; }
    out.push(Number(v));
}

function parseMsg(buf) {
    const fields = [];
    let pos = 0;
    while (pos < buf.length) {
        const start = pos;
        let key;
        [key, pos] = readVarint(buf, pos);
        const num = Number(key >> 3n), wt = Number(key & 7n);
        let vs = pos, ve;
        if (wt === 0) { [, pos] = readVarint(buf, pos); ve = pos; }
        else if (wt === 1) { pos += 8; ve = pos; }
        else if (wt === 2) { let len; [len, pos] = readVarint(buf, pos); vs = pos; pos += Number(len); ve = pos; }
        else if (wt === 5) { pos += 4; ve = pos; }
        else throw new Error("protobuf: unsupported wire type " + wt);
        if (pos > buf.length) throw new Error("protobuf: truncated field");
        fields.push({ num, wt, start, end: pos, vs, ve });
    }
    return fields;
}

function putLen(out, num, bytes) {
    writeVarint(out, (num << 3) | 2);
    writeVarint(out, bytes.length);
    for (const b of bytes) out.push(b);
}

const wrapVarint = (v) => { const w = []; writeVarint(w, 8); writeVarint(w, v); return w; };
const wrapString = (str) => { const w = []; putLen(w, 1, Array.from(new TextEncoder().encode(str))); return w; };
const packFixed64 = (ids) => {
    const out = [];
    for (const id of ids) { let v = BigInt(id); for (let i = 0; i < 8; i++) { out.push(Number(v & 0xffn)); v >>= 8n; } }
    return out;
};

// One GuildFolder message. Existing folders keep every field we don't touch (color, flags, icon...).
function buildFolderBytes(entry, raw) {
    const out = [];
    putLen(out, 1, packFixed64(entry.t === "g" ? [entry.id] : entry.guilds));
    if (entry.t === "g") return out;
    if (raw) {
        for (const f of parseMsg(raw)) {
            if (f.num === 1 || f.num === 3) continue;
            for (const b of raw.slice(f.start, f.end)) out.push(b);
        }
    } else {
        putLen(out, 2, wrapVarint(entry.id));
        if (entry.color != null) putLen(out, 4, wrapVarint(entry.color));
    }
    if (entry.name) putLen(out, 3, wrapString(entry.name));
    return out;
}

// Builds the PATCH body (guild_folders = field 14 of PreloadedUserSettings) from the current settings bytes.
function buildSettingsBody(current, layout) {
    const top = parseMsg(current);
    const gf = top.filter((f) => f.num === 14 && f.wt === 2).pop();
    const gfBytes = gf ? current.slice(gf.vs, gf.ve) : new Uint8Array(0);
    const gfFields = parseMsg(gfBytes);

    const existing = new Map();
    for (const f of gfFields) {
        if (f.num !== 1 || f.wt !== 2) continue;
        const fb = gfBytes.slice(f.vs, f.ve);
        const idf = parseMsg(fb).find((x) => x.num === 2 && x.wt === 2);
        if (!idf) continue;
        const wb = fb.slice(idf.vs, idf.ve);
        const wf = parseMsg(wb).find((x) => x.num === 1 && x.wt === 0);
        if (wf) existing.set(String(readVarint(wb, wf.vs)[0]), fb);
    }

    const msg = [];
    for (const f of gfFields) {
        if ((f.num === 1 || f.num === 2) && f.wt === 2) continue; // folders + positions are rewritten below
        for (const b of gfBytes.slice(f.start, f.end)) msg.push(b);
    }
    for (const e of layout) putLen(msg, 1, buildFolderBytes(e, e.t === "f" ? existing.get(String(e.id)) : null));
    // guild_positions: every server in sidebar order (matches the folders, so nothing contradicts them)
    putLen(msg, 2, packFixed64(layout.flatMap((e) => (e.t === "g" ? [e.id] : e.guilds))));

    const partial = [];
    putLen(partial, 14, msg);

    let version = null;
    const vf = top.find((f) => f.num === 1 && f.wt === 2);
    if (vf) {
        const vb = current.slice(vf.vs, vf.ve);
        const d = parseMsg(vb).find((x) => x.num === 3 && x.wt === 0);
        if (d) version = Number(readVarint(vb, d.vs)[0]);
    }
    const body = { settings: bytesToB64(partial) };
    if (version != null) body.required_data_version = version;
    return body;
}

module.exports = class ServList {
    constructor(meta) {
        this.meta = meta || { name: "ServList", version: "5.0.0" };
        const N = this.meta.name;
        // First run under this name: carry over what ServGrid / ServerGridSync had saved
        const load = (k) => {
            const own = BdApi.Data.load(N, k);
            if (own != null) return own;
            for (const old of ["ServGrid", "ServerGridSync"]) {
                try { const v = BdApi.Data.load(old, k); if (v != null) return v; } catch (e) {}
            }
            return null;
        };
        this.overlay = null;
        this.observer = null;
        this.raf = null;
        this.drag = null;
        this.menu = null;
        this.settings = Object.assign({ rows: 6, size: 64, lineMode: "one", sync: true }, load(SETTINGS_KEY) || {});
        this.settings.sync = true; // changes are always saved to your Discord sidebar
        this.settings.lineMode = "one"; // same placement as the Discord sidebar: servers and folders mixed on one line
        this.openFolders = new Set(load(OPEN_KEY) || []);
        this.layout = [];
        this.localLayout = BdApi.Data.load(N, LAYOUT_KEY) || null;
        this.pending = null;
        this.writeChain = Promise.resolve();
        this.hidden = load(HIDDEN_KEY) || [];
        this.onKey = (e) => {
            if (e.key !== "Escape" || !this.overlay) return;
            if (this.modal) this.closeModal();
            else if (this.menu) this.closeMenu();
            else this.closeAction();
        };
        this.onResize = () => { this.position(); this.alignButton(); };
        this.rerender = () => {
            if (!this.overlay) return;
            if ((this.S.Selected?.getGuildId?.() ?? null) !== this.startGuild) { this.close(); return; }
            if (this._interacting) { this._pendingRender = true; return; }
            clearTimeout(this._rt);
            this._rt = setTimeout(() => (this._interacting ? (this._pendingRender = true) : this.render()), 120);
        };
    }

    save(key, value) { BdApi.Data.save(this.meta.name, key, value); }

    /* -------------------------------- lifecycle -------------------------------- */

    start() {
        try { this.init(); } catch (e) {
            console.error("[ServList]", e);
            BdApi.UI?.showToast?.("ServList error: " + e.message, { type: "error" });
        }
    }

    init() {
        const { Webpack } = BdApi;
        // Several candidates for Discord's HTTP client; the first one that can read the settings is used
        const RESTs = [];
        const addREST = (m) => { if (m && typeof m.get === "function" && typeof m.patch === "function" && !RESTs.includes(m)) RESTs.push(m); };
        try { addREST(Webpack.getByKeys("getAPIBaseURL", "get")); } catch (e) {}
        try { addREST(Webpack.getModule((m) => m?.del && m?.post && m?.get && m?.patch && m?.put, { searchExports: true })); } catch (e) {}
        try { addREST(Webpack.getModule((m) => m?.del && m?.post && m?.get && m?.patch, { searchExports: true })); } catch (e) {}
        try {
            for (const m of Webpack.getModule((m) => m?.del && m?.post && m?.get && m?.patch, { first: false, searchExports: true }) || []) addREST(m);
        } catch (e) {}
        const REST = RESTs[0] || null;
        this.S = {
            Sorted: Webpack.getStore?.("SortedGuildStore") ?? Webpack.getByKeys("getGuildFolders"),
            Guild: Webpack.getStore?.("GuildStore") ?? Webpack.getByKeys("getGuild", "getGuilds"),
            Read: Webpack.getStore?.("GuildReadStateStore"),
            Selected: Webpack.getStore?.("SelectedGuildStore"),
            SelectedChannel: Webpack.getStore?.("SelectedChannelStore"),
            GuildChannels: Webpack.getStore?.("GuildChannelStore"),
            FolderUtils: Webpack.getByKeys("toggleGuildFolderExpand"),
            Expanded: Webpack.getStore?.("ExpandedGuildFolderStore"),
            User: Webpack.getStore?.("UserStore"),
            Nav: Webpack.getByKeys("transitionTo", "transitionToGuild") ?? Webpack.getByKeys("transitionTo"),
            GuildActions: Webpack.getByKeys("leaveGuild"),
            REST,
            RESTs
        };

        const [btnCss, ovCss] = this.css().split("/*@@OVERLAY@@*/");
        this.overlayCss = ovCss;
        BdApi.DOM.addStyle(this.meta.name, btnCss);
        this.inject();
        BdApi.UI.showToast?.(`ServList v${this.meta.version} loaded`, { type: "success" });
        this.observer = new MutationObserver(() => {
            if (this.raf) return;
            this.raf = requestAnimationFrame(() => {
                this.raf = null;
                this.inject();
            });
        });
        this.observer.observe(document.body, { childList: true, subtree: true });
        this._winResize = () => this.alignButton();
        window.addEventListener("resize", this._winResize);
    }

    stop() {
        this.close();
        this.observer?.disconnect();
        this.observer = null;
        if (this._winResize) window.removeEventListener("resize", this._winResize);
        document.getElementById("sg-button-wrap")?.remove();
        BdApi.DOM.removeStyle(this.meta.name);
    }

    /* --------------------------------- button --------------------------------- */

    inject() {
        const home = document.querySelector('[data-list-item-id="guildsnav___home"]');
        if (!home) return;

        let anchor = home.closest('[class*="listItem_"]') || home.parentElement;

        const nav = home.closest("nav") || home.closest('[class*="guilds_"]') || document.body;
        const readAll = [...nav.querySelectorAll("*")].find(
            (el) => el.id !== "sg-button" && el.children.length === 0 && /^\s*(read\s*all|tout\s*lire)\s*$/i.test(el.textContent || "")
        );
        if (readAll) {
            let a = readAll;
            while (a.parentElement && !a.parentElement.contains(home)) a = a.parentElement;
            if (a && a !== home && !a.contains(home)) anchor = a;
        }

        let wrap = document.getElementById("sg-button-wrap");
        if (!wrap) {
            wrap = document.createElement("div");
            wrap.id = "sg-button-wrap";
            const btn = document.createElement("div");
            btn.id = "sg-button";
            btn.title = "Serv List";
            btn.addEventListener("click", () => (this.overlay ? this.close() : this.open()));
            wrap.append(btn);
            if (this.overlay) btn.classList.add("active");
        }
        if (wrap.previousElementSibling !== anchor) {
            anchor.after(wrap);
            this.alignButton();
        }
    }

    // Centre the button on the same vertical line as Discord's own server icons
    alignButton() {
        const align = () => {
            const btn = document.getElementById("sg-button");
            const home = document.querySelector('[data-list-item-id="guildsnav___home"]');
            if (!btn || !home) return;
            btn.style.left = "0px";
            const h = home.getBoundingClientRect(), b = btn.getBoundingClientRect();
            if (!h.width || !b.width) return;
            const dx = h.left + h.width / 2 - (b.left + b.width / 2);
            if (Math.abs(dx) > 0.5) btn.style.left = Math.round(dx * 10) / 10 + "px";
        };
        requestAnimationFrame(align);
        setTimeout(align, 400);
        setTimeout(align, 1500);
    }

    /* -------------------------------- overlay -------------------------------- */

    open() {
        if (this.overlay) return;
        const host = document.createElement("div");
        host.id = "sg-overlay";
        const imp = (k, v) => host.style.setProperty(k, v, "important");
        imp("position", "fixed"); imp("right", "0"); imp("bottom", "0");
        host.setAttribute("popover", "manual");
        imp("z-index", "2147483647"); imp("background", "#4a1f8c"); imp("opacity", "1");
        imp("width", "auto"); imp("height", "auto"); imp("margin", "0"); imp("padding", "0");
        imp("border", "0"); imp("max-width", "none"); imp("max-height", "none"); imp("overflow", "hidden");
        imp("display", "block"); imp("visibility", "visible"); imp("pointer-events", "auto");
        imp("transform", "none"); imp("filter", "none");
        host.addEventListener("contextmenu", (e) => e.preventDefault());

        this.root = host.attachShadow({ mode: "open" });
        const st = document.createElement("style");
        st.textContent = this.overlayCss;
        this.app = this.h("div", { class: "sg-app" });
        this.view = this.h("div", { class: "sg-view" });
        this.openBtn = this.h("div", { class: "sg-actionbtn sg-openbtn", title: "Expand all folders", onclick: () => this.openAllFolders() }, "Open folders");
        this.closeBtn = this.h("div", { class: "sg-actionbtn sg-closebtn", title: "Collapse all open folders", onclick: () => this.closeFolders() }, "Close folders");
        this.actions = this.h("div", { class: "sg-actions" }, this.openBtn, this.closeBtn);
        this.logoMark = this.h("div", { class: "sg-logo" });
        this.app.append(this.logoMark, this.view, this.actions);
        this.app.addEventListener("click", () => this.closeMenu());
        this.root.append(st, this.app);

        this.overlay = host;
        this.startGuild = this.S.Selected?.getGuildId?.() ?? null;
        document.body.appendChild(host);
        try { host.showPopover(); } catch (e) { console.warn("[ServList] showPopover not available", e); }
        document.getElementById("sg-button")?.classList.add("active");
        this.position();
        this.render();
        setTimeout(() => this.offerMigration(), 300);

        document.addEventListener("keydown", this.onKey);
        window.addEventListener("resize", this.onResize);
        const { Sorted, Guild, Read, Selected } = this.S;
        [Sorted, Guild, Read, Selected].forEach((s) => s?.addChangeListener?.(this.rerender));
    }

    close() {
        if (!this.overlay) return;
        const { Sorted, Guild, Read, Selected } = this.S;
        [Sorted, Guild, Read, Selected].forEach((s) => s?.removeChangeListener?.(this.rerender));
        document.removeEventListener("keydown", this.onKey);
        window.removeEventListener("resize", this.onResize);
        try { this.overlay.hidePopover(); } catch (e) {}
        this.overlay.remove();
        this.overlay = null;
        this.menu = null;
        this.modal = null;
        document.getElementById("sg-button")?.classList.remove("active");
    }

    // Close button: collapses open folders, otherwise goes back to the previous page
    // Collapses every folder (never closes the page)
    closeFolders() {
        this.openFolders.clear();
        this.save(OPEN_KEY, []);
        this.render();
    }

    // Expands every folder
    openAllFolders() {
        for (const i of this.items()) if (i.type === "folder") this.openFolders.add(i.id);
        this.save(OPEN_KEY, [...this.openFolders]);
        this.render();
    }

    // Esc: collapses open folders first, then closes the page
    closeAction() {
        const anyOpen = this.items().some((i) => i.type === "folder" && this.openFolders.has(i.id));
        if (anyOpen) {
            this.openFolders.clear();
            this.save(OPEN_KEY, []);
            this.render();
        } else this.close();
    }

    position() {
        if (!this.overlay) return;
        const nav = document.querySelector('nav[class*="wrapper_"], [class*="guilds_"]');
        const bar = document.querySelector('[class*="titleBar_"]');
        const home = document.querySelector('[data-list-item-id="guildsnav___home"]');
        let left = 72;
        if (home) {
            const sidebar = home.closest("nav") || home.closest('[class*="guilds_"]') || nav;
            if (sidebar) left = sidebar.getBoundingClientRect().right;
        }
        const top = bar ? bar.getBoundingClientRect().bottom : 0;
        this.overlay.style.setProperty("left", left + "px", "important");
        this.overlay.style.setProperty("top", top + "px", "important");
    }

    /* ----------------------------------- data ----------------------------------- */

    guildData(id) {
        const g = this.S.Guild?.getGuild?.(id);
        if (!g) return null;
        let mentions = 0, unread = false, owner = false;
        try { mentions = this.S.Read?.getMentionCount?.(id) || 0; } catch (e) {}
        try { unread = !!this.S.Read?.hasUnread?.(id); } catch (e) {}
        try { owner = g.ownerId && g.ownerId === this.S.User?.getCurrentUser?.()?.id; } catch (e) {}
        return { id, name: g.name, icon: g.icon, mentions, unread, owner };
    }

    iconURL(g) {
        return g.icon ? `https://cdn.discordapp.com/icons/${g.id}/${g.icon}.webp?size=128` : null;
    }

    /* ------------------------- layout (local organization) ------------------------- */

    // Discord's real folder structure (the source of truth, same order as the sidebar)
    seedLayout() {
        const raw = this.S.Sorted?.getGuildFolders?.() || [];
        return raw.map((f) =>
            f.folderId == null
                ? { t: "g", id: String(f.guildIds[0]) }
                : { t: "f", id: String(f.folderId), name: f.folderName || "", color: f.folderColor ?? null, guilds: f.guildIds.map(String) }
        );
    }

    sig(layout) {
        return layout.map((e) => (e.t === "g" ? "G" + e.id : "F" + e.id + "|" + (e.name || "") + "|" + e.guilds.join(","))).join(";");
    }

    // Local mode (default): our own saved layout, started from Discord's order. New servers go first, like in Discord.
    // Sync mode: Discord's real order (or our edit while Discord is still catching up).
    syncLayout() {
        if (this.settings.sync) {
            const fresh = this.seedLayout();
            if (this.pending && (Date.now() > this.pending.until || this.sig(fresh) === this.pending.sig)) this.pending = null;
            if (!this.pending) this._storeSnapshot = JSON.stringify(fresh);
            this.layout = this.pending ? this.pending.layout : fresh;
            return;
        }

        let changed = false;
        if (!this.localLayout) {
            const seed = this.seedLayout();
            if (!seed.length) { this.layout = []; return; }
            this.localLayout = seed;
            changed = true;
        }
        const known = new Set(Object.keys(this.S.Guild?.getGuilds?.() || {}));
        if (known.size) {
            for (const e of this.localLayout) {
                if (e.t !== "f") continue;
                const n = e.guilds.length;
                e.guilds = e.guilds.filter((id) => known.has(id));
                if (e.guilds.length !== n) changed = true;
            }
            const n0 = this.localLayout.length;
            this.localLayout = this.localLayout.filter((e) => (e.t === "f" ? e.guilds.length > 0 : known.has(e.id)));
            if (this.localLayout.length !== n0) changed = true;
            const present = new Set(this.localLayout.flatMap((e) => (e.t === "f" ? e.guilds : [e.id])));
            const missing = [...known].filter((id) => !present.has(id));
            if (missing.length) { this.localLayout.unshift(...missing.map((id) => ({ t: "g", id }))); changed = true; }
        }
        if (changed) this.save(LAYOUT_KEY, this.localLayout);
        this.layout = this.localLayout;
    }

    // Same order as your layout (initially copied from Discord)
    items() {
        this.syncLayout();
        const hidden = new Set(this.hidden);
        const out = [];
        for (const e of this.layout) {
            if (e.t === "g") {
                if (hidden.has(e.id)) continue;
                const g = this.guildData(e.id);
                if (g) out.push({ type: "guild", guild: g });
            } else {
                const guilds = e.guilds.filter((id) => !hidden.has(id)).map((id) => this.guildData(id)).filter(Boolean);
                if (guilds.length) out.push({ type: "folder", id: e.id, name: e.name, color: e.color, guilds });
            }
        }
        return out;
    }

    findGuild(gid) {
        for (let i = 0; i < this.layout.length; i++) {
            const e = this.layout[i];
            if (e.t === "g" && e.id === gid) return { loc: "top", i };
            if (e.t === "f") {
                const j = e.guilds.indexOf(gid);
                if (j >= 0) return { loc: "in", i, j, f: e };
            }
        }
        return null;
    }

    nextColor() {
        const palette = [0x5865f2, 0xeb459e, 0xfee75c, 0x57f287, 0xed4245, 0xff9f1a, 0x9b59ff];
        return palette[this.layout.filter((e) => e.t === "f").length % palette.length];
    }

    newFolderId() {
        const used = new Set(this.layout.filter((e) => e.t === "f").map((e) => e.id));
        let id;
        do { id = String(Math.floor(Math.random() * 4294967294) + 1); } while (used.has(id));
        return id;
    }

    commit() {
        this.layout = this.layout.filter((e) => e.t === "g" || e.guilds.length > 0);
        if (!this.settings.sync) {
            this.localLayout = this.layout;
            this.save(LAYOUT_KEY, this.localLayout);
            this.save(OPEN_KEY, [...this.openFolders]);
            this.render();
            return;
        }
        const base = this.pending ? this.pending.sig : this.sig(JSON.parse(this._storeSnapshot || "[]"));
        const next = this.sig(this.layout);
        this.save(OPEN_KEY, [...this.openFolders]);
        if (next === base) { this.render(); return; } // nothing changed

        // Safety net: keep a copy of the folders as Discord had them before our first change
        if (!this._backedUp) {
            this._backedUp = true;
            try { this.save(BACKUP_KEY, { at: Date.now(), layout: JSON.parse(this._storeSnapshot || "[]") }); } catch (e) {}
        }
        this.pending = { layout: this.layout, sig: next, until: Date.now() + 15000 };
        this.render();
        this.pushToDiscord(this.layout);
    }

    pushToDiscord(layout) {
        const snapshot = JSON.parse(JSON.stringify(layout));
        this.writeChain = this.writeChain
            .then(() => this.writeFolders(snapshot))
            .then((canon) => this.afterWrite(canon, snapshot))
            .catch((err) => {
                console.error("[ServList] could not update Discord", err);
                this.pending = null;
                this.fail("Couldn't update Discord: " + this.describe(err));
                this.render();
            });
    }

    // Discord's HTTP client answers with the JSON in `text` (body can be empty), so we read both
    async unwrap(res) {
        const tryJSON = (v) => { try { const j = JSON.parse(v); return j && typeof j === "object" ? j : null; } catch (e) { return null; } };
        const b = res?.body;
        const isBuf = (v) => v instanceof ArrayBuffer || ArrayBuffer.isView?.(v);
        if (b && typeof b === "object" && !isBuf(b) && ("settings" in b || "message" in b || "out_of_date" in b)) return b;
        const texts = [];
        if (typeof res?.text === "string") texts.push(res.text);
        if (typeof b === "string") texts.push(b);
        let xr; try { xr = res?.xhr?.response; } catch (e) {}
        if (typeof xr === "string") texts.push(xr);
        for (const buf of [xr, b]) {
            try {
                if (isBuf(buf)) texts.push(new TextDecoder().decode(buf));
                else if (typeof Blob !== "undefined" && buf instanceof Blob) texts.push(await buf.text());
            } catch (e) {}
        }
        for (const t of texts) { const j = tryJSON(t); if (j) return j; }
        return b ?? res;
    }

    // One readable line about a response (used when something doesn't look right)
    peek(res) {
        const h = res?.headers || res?.header || {};
        const ct = h["content-type"] || h["Content-Type"] || "?";
        let rt = "?"; try { rt = res?.xhr?.responseType || "text"; } catch (e) {}
        const tx = typeof res?.text === "string" ? JSON.stringify(res.text.slice(0, 80)) : typeof res?.text;
        const bd = res?.body == null ? String(res?.body) : typeof res.body === "object" ? "{" + Object.keys(res.body).slice(0, 6).join(",") + "}" : typeof res.body;
        return `status ${res?.status ?? "?"}, type ${ct}, xhr ${rt}, text ${tx}, body ${bd}`;
    }

    // The real API address (the relative path alone ends up on the Discord web page, which answers with HTML)
    apiBase() {
        try {
            const g = window.GLOBAL_ENV;
            if (g?.API_ENDPOINT) {
                const e = String(g.API_ENDPOINT);
                return (e.startsWith("//") ? location.protocol + e : e) + "/v" + (g.API_VERSION || 9);
            }
        } catch (e) {}
        return "https://discord.com/api/v9";
    }

    async readSettings() {
        const path = "/users/@me/settings-proto/1";
        const problems = [];
        let best = null; // a connection that clearly reaches the API (even if it answered with an error)
        for (const REST of this.S.RESTs || []) {
            for (const url of [this.apiBase() + path, path]) {
                try {
                    const res = await REST.get({ url });
                    const b = await this.unwrap(res);
                    if (b && typeof b.settings === "string") return { REST, url, settings: b.settings };
                    if (b && typeof b === "object" && b !== res && !best) best = { REST, url };
                    console.warn("[ServList] unexpected settings response", url, res);
                    problems.push(`${url.startsWith("http") ? "api url" : "path"}: ${this.peek(res)}`);
                } catch (e) {
                    if (!best && e?.status >= 400 && e?.status < 500) best = { REST, url };
                    console.warn("[ServList] settings request failed", url, e);
                    problems.push((url.startsWith("http") ? "api url: " : "path: ") + this.describe(e));
                }
            }
        }
        const err = new Error("couldn't read your current settings (" + (problems.join(" | ") || "Discord's HTTP module wasn't found") + ")");
        err.best = best;
        throw err;
    }

    validateLayout(layout) {
        const seen = new Set();
        for (const e of layout) {
            const ids = e.t === "g" ? [e.id] : e.guilds;
            if (e.t === "f" && (!/^\d+$/.test(String(e.id)) || !ids.length)) throw new Error("invalid folder, nothing was changed");
            for (const id of ids) {
                if (!/^\d+$/.test(String(id))) throw new Error("invalid server id, nothing was changed");
                if (seen.has(id)) throw new Error("a server appeared twice, nothing was changed");
                seen.add(id);
            }
        }
        const known = Object.keys(this.S.Guild?.getGuilds?.() || {});
        if (known.length && known.some((id) => !seen.has(id))) throw new Error("some servers were missing from the new layout, nothing was changed");
    }

    async writeFolders(layout) {
        this.validateLayout(layout);
        let REST, url = this.apiBase() + "/users/@me/settings-proto/1", current = new Uint8Array(0), readProblem = null;
        try {
            const r = await this.readSettings();
            REST = r.REST; url = r.url; current = b64ToBytes(r.settings);
        } catch (e) {
            // Can't read the current settings: save the folders anyway (extras such as custom folder icons can't be kept)
            readProblem = e.message;
            REST = e.best?.REST || (this.S.RESTs || [])[0];
            if (e.best?.url) url = e.best.url;
            if (!REST) throw e;
            console.warn("[ServList] saving without reading your settings first:", e.message);
        }
        for (let attempt = 0; attempt < 2; attempt++) {
            let r;
            try {
                const raw = await REST.patch({ url, body: buildSettingsBody(current, layout) });
                this._lastWrite = { read: readProblem, save: this.peek(raw) };
                r = await this.unwrap(raw);
            } catch (e) {
                if (readProblem && e && typeof e === "object") e.readProblem = readProblem;
                throw e;
            }
            const canon = r?.settings;
            if (typeof canon === "string") current = b64ToBytes(canon);
            if (!r?.out_of_date) return canon;
            readProblem = null;
        }
        throw new Error("your settings changed somewhere else, please try again");
    }

    // Discord pushes the change to the sidebar by itself; we only keep our order on screen until it does
    // Short description of the first difference between what we sent and what the sidebar shows
    diffLayouts(sent, actual) {
        const str = (e) => (e.t === "g" ? "server " + e.id.slice(-4) : "folder " + e.id + " [" + e.guilds.map((g) => g.slice(-4)).join(",") + "]");
        const n = Math.max(sent.length, actual.length);
        for (let i = 0; i < n; i++) {
            const a = sent[i] ? str(sent[i]) : "(nothing)", b = actual[i] ? str(actual[i]) : "(nothing)";
            if (a !== b) return `at position ${i + 1} we sent ${a} but the sidebar has ${b}`;
        }
        return "same entries, different details";
    }

    afterWrite(canon, snapshot) {
        const expected = this.sig(snapshot);
        const reflected = () => this.sig(this.seedLayout()) === expected;
        if (this.pending && this.pending.sig === expected) this.pending.until = Date.now() + 10 * 60 * 1000;
        setTimeout(() => {
            if (!(this.pending && this.pending.sig === expected && !reflected())) return;
            const w = this._lastWrite || {};
            const diff = this.diffLayouts(snapshot, this.seedLayout());
            this.pending = null; // show what the sidebar really has, not what we hoped for
            this.render();
            this.fail("Your sidebar didn't change: " + diff + ". " +
                `Reading your settings: ${w.read ? w.read : "ok"}. Saving: ${w.save || "no answer"}.`);
        }, 6000);
    }

    // The page's arrangement from earlier versions (kept only on this page), cleaned up for today's servers
    localArrangement() {
        const was = this.settings.sync;
        this.settings.sync = false;
        this.syncLayout();
        const mine = JSON.parse(JSON.stringify(this.layout));
        this.settings.sync = was;
        this.syncLayout();
        return mine;
    }

    // Asked once: keep the arrangement made on the page before sync existed, or follow the sidebar?
    offerMigration() {
        if (this.settings.migrated || !this.overlay) return;
        this.settings.migrated = true;
        this.save(SETTINGS_KEY, this.settings);
        if (!this.localLayout) return;
        const mine = this.localArrangement();
        if (!mine.length || this.sig(mine) === this.sig(this.seedLayout())) return;
        this.openModal({
            title: "Use your page arrangement for the sidebar?",
            text: "You arranged your servers and folders on this page earlier. Apply that order to your Discord sidebar? A backup of your current Discord folders is saved first. If you choose No, the page follows your sidebar's order.",
            actions: [
                { label: "No, keep sidebar order" },
                { label: "Yes, apply", cls: "primary", fn: () => this.applyToDiscord(mine) }
            ]
        });
    }

    applyToDiscord(mine) {
        const discord = this.seedLayout();
        try { this.save(BACKUP_KEY, { at: Date.now(), layout: discord }); this._backedUp = true; } catch (e) {}
        this._storeSnapshot = JSON.stringify(discord);
        this.layout = mine;
        this.pending = { layout: mine, sig: this.sig(mine), until: Date.now() + 15000 };
        this.render();
        this.pushToDiscord(mine);
        this.flash("Saving to Discord...");
    }

    restoreBackup() {
        const b = BdApi.Data.load(this.meta.name, BACKUP_KEY);
        if (!b?.layout?.length) { this.flash("No backup saved yet."); return; }
        this.layout = b.layout;
        this.pending = null;
        this._storeSnapshot = "[]";
        this.commit();
        this.flash("Backup restored.");
    }

    // src : {kind:"guild", gid} | {kind:"folder", fid}
    // tgt : {kind:"guild-top", gid} | {kind:"folder", fid} | {kind:"guild-in", fid, gid} | {kind:"bg"}
    // zone : "before" | "after" | "into" | "bg"
    applyDrop(src, tgt, zone) {
        this.syncLayout();
        const L = this.layout;
        const idxF = (fid) => L.findIndex((e) => e.t === "f" && e.id === fid);
        const idxG = (gid) => L.findIndex((e) => e.t === "g" && e.id === gid);
        const off = zone === "after" ? 1 : 0;

        if (src.kind === "folder") {
            const fi = idxF(src.fid);
            if (fi < 0) return;
            let anchor = -1;
            if (tgt.kind === "folder" || tgt.kind === "guild-in") anchor = idxF(tgt.fid);
            else if (tgt.kind === "guild-top") anchor = idxG(tgt.gid);
            if (anchor < 0 || anchor === fi) return;
            const anchorEntry = L[anchor];
            const [entry] = L.splice(fi, 1);
            L.splice(L.indexOf(anchorEntry) + off, 0, entry);
            return this.commit();
        }

        const where = this.findGuild(src.gid);
        if (!where) return;
        if (tgt.kind === "bg" && where.loc === "top") return;
        if (tgt.kind === "guild-top" && tgt.gid === src.gid) return;
        if (tgt.kind === "guild-in" && tgt.gid === src.gid) return;

        let tEntry = null;
        if (tgt.kind === "folder" || tgt.kind === "guild-in") tEntry = L[idxF(tgt.fid)];
        else if (tgt.kind === "guild-top") tEntry = L[idxG(tgt.gid)];
        if (tgt.kind !== "bg" && !tEntry) return;
        if (tgt.kind === "folder" && zone === "into" && where.f === tEntry) return;

        // remove the server from its current position
        if (where.loc === "top") L.splice(where.i, 1);
        else where.f.guilds.splice(where.j, 1);

        const single = { t: "g", id: src.gid };
        if (tgt.kind === "bg") {
            const at = where.loc === "in" ? L.indexOf(where.f) : -1;
            if (at >= 0) L.splice(at + 1, 0, single);
            else L.push(single);
        } else if (tgt.kind === "guild-top") {
            const at = L.indexOf(tEntry);
            if (zone === "into") {
                const folder = { t: "f", id: this.newFolderId(), name: "", color: this.nextColor(), guilds: [tgt.gid, src.gid] };
                L.splice(at, 1, folder);
                this.openFolders.add(folder.id);
            } else L.splice(at + off, 0, single);
        } else if (tgt.kind === "folder") {
            if (zone === "into") tEntry.guilds.push(src.gid);
            else L.splice(L.indexOf(tEntry) + off, 0, single);
        } else if (tgt.kind === "guild-in") {
            const j = tEntry.guilds.indexOf(tgt.gid);
            tEntry.guilds.splice(j + off, 0, src.gid);
        }
        this.commit();
    }

    // Move one slot via the menu (dir = -1 left/up, +1 right/down)
    moveStep(kind, id, dir, folderId) {
        this.syncLayout();
        const hidden = new Set(this.hidden);
        let arr, i, vis;
        if (folderId) {
            arr = this.layout.find((e) => e.t === "f" && e.id === folderId)?.guilds || [];
            i = arr.indexOf(id);
            vis = (x) => !hidden.has(x);
        } else {
            arr = this.layout;
            i = arr.findIndex((e) => e.t === kind && e.id === id);
            vis = (e) => (e.t === "f" ? e.guilds.some((g) => !hidden.has(g)) : !hidden.has(e.id));
        }
        if (i < 0) return;
        let j = i + dir;
        while (j >= 0 && j < arr.length && !vis(arr[j])) j += dir;
        if (j < 0 || j >= arr.length) return;
        const [x] = arr.splice(i, 1);
        arr.splice(j, 0, x);
        this.commit();
    }

    ungroup(fid) {
        this.syncLayout();
        const i = this.layout.findIndex((e) => e.t === "f" && e.id === fid);
        if (i < 0) return;
        const f = this.layout[i];
        this.layout.splice(i, 1, ...f.guilds.map((id) => ({ t: "g", id })));
        this.openFolders.delete(fid);
        this.commit();
    }

    takeOut(gid) {
        this.syncLayout();
        const w = this.findGuild(gid);
        if (!w || w.loc !== "in") return;
        w.f.guilds.splice(w.j, 1);
        this.layout.splice(w.i + 1, 0, { t: "g", id: gid });
        this.commit();
    }

    /* --------------------------------- render --------------------------------- */

    h(tag, props = {}, ...kids) {
        const e = document.createElement(tag);
        for (const [k, v] of Object.entries(props || {})) {
            if (k === "class") e.className = v;
            else if (k === "style") e.style.cssText = v;
            else if (k.startsWith("on")) e.addEventListener(k.slice(2), v);
            else e.setAttribute(k, v);
        }
        for (const c of kids.flat()) if (c != null) e.append(c);
        return e;
    }

    makeDraggable(el, src, onActivate) {
        el.dataset.kind = src.kind;
        el.dataset.loc = src.loc;
        if (src.gid) el.dataset.gid = src.gid;
        if (src.fid) el.dataset.fid = src.fid;

        el.addEventListener("pointerdown", (e) => {
            if (e.button !== 0) return;
            this._interacting = true;
            const sx = e.clientX, sy = e.clientY;
            let started = false, ghost = null, tgt = null, zone = null;

            const clearTarget = () => {
                this.root.querySelectorAll(".drop-before, .drop-after, .drop-into, .drop-bg").forEach((n) => n.classList.remove("drop-before", "drop-after", "drop-into", "drop-bg"));
            };

            const move = (ev) => {
                if (!started) {
                    if (Math.hypot(ev.clientX - sx, ev.clientY - sy) < 6) return;
                    started = true;
                    el.classList.add("dragging");
                    ghost = el.cloneNode(true);
                    ghost.classList.remove("dragging");
                    ghost.classList.add("sg-ghost");
                    this.app.append(ghost);
                }
                const r = this.overlay.getBoundingClientRect();
                ghost.style.left = ev.clientX - r.left - 42 + "px";
                ghost.style.top = ev.clientY - r.top - 40 + "px";

                clearTarget();
                tgt = null;
                zone = null;
                const hit = this.root.elementFromPoint(ev.clientX, ev.clientY);
                const under = hit?.closest?.(".sg-tile");
                if (under && under !== el) {
                    const inPanel = under.dataset.loc === "in";
                    tgt = {
                        kind: under.dataset.kind === "folder" ? "folder" : inPanel ? "guild-in" : "guild-top",
                        gid: under.dataset.gid,
                        fid: under.dataset.fid
                    };
                    const b = under.getBoundingClientRect();
                    const fx = (ev.clientX - b.left) / b.width;
                    const fy = (ev.clientY - b.top) / b.height;
                    if ((this.settings.lineMode === "rows") && src.kind === "folder" && tgt.kind === "guild-top") {
                        tgt = null; // a folder can't be placed among the single servers on their own line
                    } else {
                        if (inPanel) zone = fy < 0.5 ? "before" : "after";
                        else if ((this.settings.lineMode === "rows") && src.kind === "guild" && tgt.kind === "folder") zone = "into";
                        else if (src.kind === "guild") zone = fx < 0.25 ? "before" : fx > 0.75 ? "after" : "into";
                        else zone = fx < 0.5 ? "before" : "after";
                        under.classList.add("drop-" + zone);
                    }
                } else if (!under && src.kind === "guild" && src.loc === "in" && hit?.closest?.(".sg-scroll") && !hit.closest(".sg-folder")) {
                    tgt = { kind: "bg" };
                    zone = "bg";
                    hit.closest(".sg-scroll").classList.add("drop-bg");
                }
            };

            const up = () => {
                document.removeEventListener("pointermove", move, true);
                document.removeEventListener("pointerup", up, true);
                document.removeEventListener("pointercancel", up, true);
                this._interacting = false;
                if (started) {
                    ghost?.remove();
                    el.classList.remove("dragging");
                    clearTarget();
                    if (tgt) this.applyDrop(src, tgt, zone);
                } else {
                    // plain click: handled here so a re-render can never swallow it
                    onActivate?.();
                }
                if (this._pendingRender && this.overlay) {
                    this._pendingRender = false;
                    this.render();
                }
            };

            document.addEventListener("pointermove", move, true);
            document.addEventListener("pointerup", up, true);
            document.addEventListener("pointercancel", up, true);
        });
    }

    badge(g) {
        if (g.mentions > 0) return this.h("div", { class: "sg-badge" }, g.mentions > 99 ? "99+" : String(g.mentions));
        if (g.unread) return this.h("div", { class: "sg-dot" });
        return null;
    }

    guildIcon(g) {
        const url = this.iconURL(g);
        if (url) return this.h("img", { src: url, alt: g.name, loading: "lazy", draggable: "false" });
        const acro = g.name.split(/\s+/).map((w) => w[0]).join("").slice(0, 3);
        return this.h("span", { class: "sg-acro" }, acro);
    }

    guildTile(g, container) {
        const active = this.S.Selected?.getGuildId?.() === g.id;
        const inFolder = container.startsWith("f:");
        const fid = inFolder ? container.slice(2) : null;
        const tile = this.h(
            "div",
            {
                class: "sg-tile" + (active ? " current" : "") + (inFolder ? " axis-y" : ""),
                title: g.name,
                oncontextmenu: (e) => this.showMenu(e, g, fid)
            },
            this.h("div", { class: "sg-icon" }, this.guildIcon(g), this.badge(g)),
            this.h("div", { class: "sg-name" }, g.name)
        );
        this.makeDraggable(tile, { kind: "guild", gid: g.id, fid, loc: inFolder ? "in" : "top" }, () => this.go(g.id, fid));
        return tile;
    }

    folderBlock(f) {
        const open = this.openFolders.has(f.id);
        const color = "#" + ((f.color ?? 0x5865f2) & 0xffffff).toString(16).padStart(6, "0");
        const mentions = f.guilds.reduce((a, g) => a + g.mentions, 0);
        const unread = f.guilds.some((g) => g.unread);

        const mini = this.h(
            "div",
            { class: "sg-mini" },
            f.guilds.slice(0, 4).map((g) => {
                const url = this.iconURL(g);
                return url
                    ? this.h("img", { src: url, draggable: "false" })
                    : this.h("span", { class: "sg-mini-acro" }, g.name[0]);
            })
        );

        const tile = this.h(
            "div",
            {
                class: "sg-tile sg-folder-tile",
                title: f.name || "Folder",
                oncontextmenu: (e) => this.showFolderMenu(e, f),

            },
            this.h(
                "div",
                { class: "sg-icon sg-folder-icon", style: `background:${color}33;border-color:${color}` },
                mini,
                this.badge({ mentions, unread })
            ),
            this.h("div", { class: "sg-name" }, (f.name || "Folder") + ` (${f.guilds.length})`)
        );
        this.makeDraggable(tile, { kind: "folder", fid: f.id, loc: "top" }, () => {
            open ? this.openFolders.delete(f.id) : this.openFolders.add(f.id);
            this.save(OPEN_KEY, [...this.openFolders]);
            this.render();
        });

        const block = this.h("div", { class: "sg-folder" + (open ? " open" : ""), style: open ? `border-color:${color}66` : "" }, tile);

        if (open) {
            const rows = Math.max(1, Math.min(this.settings.rows, f.guilds.length));
            block.append(
                this.h(
                    "div",
                    { class: "sg-panel", style: `grid-template-rows:repeat(${rows}, auto)` },
                    f.guilds.map((g) => this.guildTile(g, "f:" + f.id))
                )
            );
        }
        return block;
    }

    render() {
        if (!this.overlay || !this.view) return;
        const scroll = this.view.querySelector(".sg-scroll")?.scrollTop || 0;
        const items = this.items();
        const count = items.reduce((a, i) => a + (i.type === "guild" ? 1 : i.guilds.length), 0);

        const header = this.h(
            "div",
            { class: "sg-header" },
            this.h("div", { class: "sg-title" }, "Servers"),
            this.h("div", { class: "sg-count" }, `${count} servers · drag to organize, drop on an icon to make a folder · v${this.meta.version} · Author: ${this.meta.author || "WeConnected"}`),
            this.hidden.length
                ? this.h("div", {
                    class: "sg-restore",
                    title: "Show hidden servers",
                    onclick: () => { this.hidden = []; this.save(HIDDEN_KEY, []); this.render(); }
                }, `Show ${this.hidden.length} hidden`)
                : null,
            this.h("div", { class: "sg-x", title: "Close menu", onclick: () => this.close() }, "✕")
        );

        const rows = [];
        if ((this.settings.lineMode === "rows")) {
            const folders = items.filter((i) => i.type === "folder");
            const singles = items.filter((i) => i.type === "guild");
            if (folders.length) rows.push(this.h("div", { class: "sg-grid" }, folders.map((f) => this.folderBlock(f))));
            if (singles.length) rows.push(this.h("div", { class: "sg-grid" }, singles.map((i) => this.guildTile(i.guild, "top"))));
        } else {
            rows.push(this.h("div", { class: "sg-grid" }, items.map((i) => (i.type === "guild" ? this.guildTile(i.guild, "top") : this.folderBlock(i)))));
        }

        const body = this.h("div", { class: "sg-scroll" }, rows);
        this.app.style.setProperty("--sg-size", this.settings.size + "px");
        this.view.replaceChildren(header, body);
        body.scrollTop = scroll;

    }

    /* ------------------------------ menus / dialogs ------------------------------ */

    closeMenu() { this.menu?.remove(); this.menu = null; }
    closeModal() { this.modal?.remove(); this.modal = null; }

    popMenu(e, title, entries) {
        e.preventDefault();
        e.stopPropagation();
        this.closeMenu();
        const r = this.overlay.getBoundingClientRect();
        const kids = [this.h("div", { class: "sg-menu-title" }, title)];
        for (const en of entries) {
            if (!en) continue;
            if (en === "sep") { kids.push(this.h("div", { class: "sg-menu-sep" })); continue; }
            const [label, fn, cls] = en;
            kids.push(this.h("div", { class: "sg-menu-item " + (cls || ""), onclick: (ev) => { ev.stopPropagation(); this.closeMenu(); fn(); } }, label));
        }
        const menu = this.h("div", { class: "sg-menu" }, kids);
        menu.style.left = Math.max(8, Math.min(e.clientX - r.left, r.width - 240)) + "px";
        menu.style.top = Math.max(8, Math.min(e.clientY - r.top, r.height - 50 - entries.length * 34)) + "px";
        this.app.append(menu);
        this.menu = menu;
    }

    showMenu(e, g, fid) {
        this.popMenu(e, g.name, [
            ["Open server", () => this.go(g.id, fid)],
            ["◀ Move left", () => this.moveStep("g", g.id, -1, fid)],
            ["Move right ▶", () => this.moveStep("g", g.id, 1, fid)],
            fid ? ["Remove from folder", () => this.takeOut(g.id)] : null,
            ["Hide from this page", () => {
                if (!this.hidden.includes(g.id)) this.hidden.push(g.id);
                this.save(HIDDEN_KEY, this.hidden);
                this.render();
                this.flash(`${g.name} hidden (undo at the top right)`);
            }],
            "sep",
            ["Leave server…", () => this.confirmLeave(g), "danger"]
        ]);
    }

    showFolderMenu(e, f) {
        this.popMenu(e, f.name || "Folder", [
            ["Rename folder…", () => this.renameFolder(f)],
            ["◀ Move left", () => this.moveStep("f", f.id, -1)],
            ["Move right ▶", () => this.moveStep("f", f.id, 1)],
            "sep",
            ["Dissolve folder", () => this.ungroup(f.id)]
        ]);
    }

    openModal({ title, text, input, actions }) {
        this.closeModal();
        let field = null;
        const btns = actions.map((a) =>
            this.h("div", {
                class: "sg-btn " + (a.cls || ""),
                onclick: () => { const v = field?.value; this.closeModal(); a.fn?.(v); }
            }, a.label)
        );
        const kids = [this.h("div", { class: "sg-modal-title" }, title)];
        if (text) kids.push(this.h("div", { class: "sg-modal-text" }, text));
        if (input) {
            field = this.h("input", { class: "sg-input", type: "text", value: input.value || "", placeholder: input.placeholder || "" });
            field.addEventListener("keydown", (e) => {
                e.stopPropagation();
                if (e.key === "Enter") btns[btns.length - 1].click();
                else if (e.key === "Escape") this.closeModal();
            });
            kids.push(field);
        }
        kids.push(this.h("div", { class: "sg-modal-actions" }, btns));
        const modal = this.h("div", { class: "sg-modal", onclick: (ev) => ev.stopPropagation() }, this.h("div", { class: "sg-modal-box" }, kids));
        this.app.append(modal);
        this.modal = modal;
        if (field) setTimeout(() => { field.focus(); field.select(); }, 0);
    }

    renameFolder(f) {
        this.openModal({
            title: "Rename folder",
            input: { value: f.name || "", placeholder: "Folder name" },
            actions: [
                { label: "Cancel" },
                { label: "Save", cls: "primary", fn: (v) => {
                    this.syncLayout();
                    const e = this.layout.find((x) => x.t === "f" && x.id === f.id);
                    if (e) { e.name = (v || "").trim().slice(0, 32); this.commit(); }
                } }
            ]
        });
    }

    confirmLeave(g) {
        const actions = [{ label: "Cancel" }];
        if (!g.owner) actions.push({ label: "Leave", cls: "danger", fn: () => this.leave(g) });
        this.openModal({
            title: `Leave "${g.name}"?`,
            text: g.owner
                ? "You own this server, so you can't leave it. Transfer ownership or delete it from Discord first."
                : "You'll need a new invite to come back. This can't be undone.",
            actions
        });
    }

    async leave(g) {
        try {
            const A = this.S.GuildActions;
            if (A?.leaveGuild) await A.leaveGuild(g.id);
            else if (this.S.REST?.del) await this.S.REST.del({ url: `/users/@me/guilds/${g.id}`, body: { lurking: false } });
            else throw new Error("Discord function not found");
            this.flash(`You left ${g.name}`);
        } catch (err) {
            console.error("[ServList] leave", err);
            this.flash("Couldn't leave: " + (err?.message || err));
        }
    }

    // Turns whatever Discord's HTTP client rejects with into a readable line
    describe(err) {
        const parts = [];
        const status = err?.status ?? err?.statusCode ?? err?.response?.status;
        if (status) parts.push("HTTP " + status);
        let msg = err?.body?.message || err?.response?.body?.message;
        if (!msg && typeof err?.text === "string") {
            try { msg = JSON.parse(err.text).message || err.text.slice(0, 200); } catch (e) { msg = err.text.slice(0, 200); }
        }
        msg = msg || err?.message || (typeof err === "string" ? err : "");
        if (err?.body?.code) parts.push("code " + err.body.code);
        if (msg) parts.push(msg);
        if (err?.readProblem) parts.push("earlier: " + err.readProblem);
        if (err?.body?.errors) parts.push(JSON.stringify(err.body.errors).slice(0, 300));
        return parts.join(" - ") || String(err);
    }

    // Long-lived error: stays on screen and is copied so you can paste it to someone
    fail(text) {
        console.error("[ServList] " + text);
        let copied = false;
        try { navigator.clipboard?.writeText?.(`ServList v${this.meta.version}: ${text}`); copied = true; } catch (e) {}
        this.flash(text + (copied ? "  (copied to your clipboard - click to dismiss)" : "  (click to dismiss)"), 30000);
    }

    flash(text, ms = 3500) {
        if (!this.app) { BdApi.UI?.showToast?.(text); return; }
        const t = this.h("div", { class: "sg-toast", onclick: () => t.remove() }, text);
        this.app.append(t);
        setTimeout(() => t.remove(), ms);
    }

    // The channel to land in: the one you last used in that server, otherwise its default channel
    channelFor(id) {
        try {
            const last = this.S.SelectedChannel?.getMostRecentSelectedTextChannelId?.(id);
            if (last) return last;
        } catch (e) {}
        try {
            const def = this.S.GuildChannels?.getDefaultChannel?.(id);
            if (def?.id) return def.id;
        } catch (e) {}
        return null;
    }

    sidebarItem(id) {
        return document.querySelector(`[data-list-item-id="guildsnav___${id}"]`);
    }

    // Opens a server. Several ways, each one checked: straight to a channel, Discord's other helper,
    // then (for servers in folders) expanding the folder in the sidebar and clicking the server there.
    go(id, fid) {
        this.close();
        const { Nav, Selected } = this.S;
        const current = () => Selected?.getGuildId?.() ?? null;
        const opened = () => current() === id;
        const wait = (ms) => new Promise((r) => setTimeout(r, ms));
        const channel = this.channelFor(id);
        const path = channel ? `/channels/${id}/${channel}` : `/channels/${id}`;
        const startedIn = current();
        const log = [];
        console.log("[ServList] opening server", id, "in folder", fid ?? "-", "->", path, "| currently in", startedIn);

        (async () => {
            try {
                if (Nav?.transitionTo) Nav.transitionTo(path); else if (Nav?.transitionToGuild) Nav.transitionToGuild(id);
                log.push("transitionTo(path)");
            } catch (e) { log.push("transitionTo threw: " + e.message); }
            await wait(500);
            if (opened()) return;

            try { Nav?.transitionToGuild?.(id, channel || undefined); log.push("transitionToGuild"); } catch (e) { log.push("transitionToGuild threw: " + e.message); }
            await wait(600);
            if (opened()) return;

            // like clicking the server icon in the left sidebar (expanding its folder first if needed)
            let el = this.sidebarItem(id);
            if (!el && fid != null) {
                try {
                    const expanded = this.S.Expanded?.isFolderExpanded?.(Number(fid));
                    if (!expanded && this.S.FolderUtils?.toggleGuildFolderExpand) {
                        this.S.FolderUtils.toggleGuildFolderExpand(Number(fid));
                        log.push("expanded folder in sidebar");
                        await wait(500);
                    }
                } catch (e) { log.push("folder expand threw: " + e.message); }
                el = this.sidebarItem(id);
            }
            if (el) { el.click(); log.push("clicked sidebar icon"); } else log.push("sidebar icon not found");
            await wait(900);
            if (opened()) return;

            const name = this.S.Guild?.getGuild?.(id)?.name || "?";
            const report = [
                `ServList v${this.meta.version} couldn't switch to "${name}" (${id}).`,
                `Path tried: ${path}`,
                `You were in: ${startedIn ?? "no server"}; now in: ${current() ?? "no server"}`,
                `Folder: ${fid ?? "none"}; folder open in sidebar: ${this.S.Expanded?.isFolderExpanded ? String(this.S.Expanded.isFolderExpanded(Number(fid))) : "unknown"}`,
                `Steps: ${log.join(" > ")}`,
                `Discord helpers: transitionTo=${!!Nav?.transitionTo} transitionToGuild=${!!Nav?.transitionToGuild} folderToggle=${!!this.S.FolderUtils} channel=${channel ?? "none"}`
            ].join("\n");
            console.error("[ServList] " + report);
            try { navigator.clipboard?.writeText?.(report); } catch (e) {}
            if (BdApi.UI?.alert) BdApi.UI.alert("ServList couldn't open that server (details copied to your clipboard)", report);
            else BdApi.UI?.showToast?.("Couldn't open that server. Details are in the console.", { type: "error" });
        })();
    }

    /* --------------------------------- settings --------------------------------- */

    getSettingsPanel() {
        if (!BdApi.UI?.buildSettingsPanel) return document.createTextNode("Settings aren't supported by this version of BetterDiscord.");
        const restore = BdApi.React?.createElement("button", {
            onClick: () => this.restoreBackup(),
            style: { padding: "8px 16px", borderRadius: 6, border: 0, cursor: "pointer", fontWeight: 700, background: "#ff5fb0", color: "#3a0023" }
        }, "Restore backup");
        const settings = [
                { type: "slider", id: "rows", name: "Servers per column in an open folder", note: "Beyond that, they overflow to the right.", value: this.settings.rows, min: 2, max: 20, step: 1, markers: [2, 4, 6, 8, 10, 12, 16, 20] },
                { type: "slider", id: "size", name: "Icon size (px)", value: this.settings.size, min: 40, max: 120, step: 4, markers: [40, 56, 64, 80, 96, 120] }
        ];
        const onChange = (_cat, id, value) => {
            this.settings[id] = value;
            this.save(SETTINGS_KEY, this.settings);
            this.render();
        };
        if (restore) {
            try {
                return BdApi.UI.buildSettingsPanel({
                    settings: [...settings, { type: "custom", id: "restore", name: "Restore folder backup", note: "Puts your folders back the way they were before ServList's first change.", children: restore }],
                    onChange
                });
            } catch (e) { /* older BetterDiscord: fall back to the basic panel */ }
        }
        return BdApi.UI.buildSettingsPanel({ settings, onChange });
    }

    /* ----------------------------------- CSS ----------------------------------- */

    css() {
        return `
        #sg-button-wrap { display:flex; justify-content:center; width:100%; margin:2px 0 8px; }
        #sg-button {
            position:relative; left:0; width:48px; height:48px; border-radius:50%; cursor:pointer; flex:none;
            background:url("${LOGO}") center/contain no-repeat;
            filter:drop-shadow(0 2px 4px rgba(0,0,0,.45));
            transition:transform .12s, filter .12s;
        }
        #sg-button:hover { transform:scale(1.08); }
        #sg-button.active { filter:drop-shadow(0 0 3px #e7b0f7) drop-shadow(0 0 7px rgba(231,176,247,.7)); }

        /*@@OVERLAY@@*/
        :host { display:block; }
        * { box-sizing: border-box; }
        .sg-app {
            position:absolute; inset:0; overflow:hidden;
            background:#2a0a5e url("${BG}") center/cover no-repeat; color:#fff;
            font-family:var(--font-primary, "gg sans", "Noto Sans", sans-serif);
            --sg-size:64px;
            user-select:none;
        }
        .sg-view { position:absolute; inset:0; display:flex; flex-direction:column; }
        .sg-header { display:flex; align-items:center; gap:14px; padding:14px 24px; border-bottom:1px solid rgba(255,255,255,.1); }
        .sg-title { font-size:20px; font-weight:800; }
        .sg-count { opacity:.6; font-size:13px; flex:1; }
        .sg-restore { cursor:pointer; font-size:12px; padding:5px 10px; border-radius:6px; background:rgba(255,171,46,.2); color:#ffcf85; }
        .sg-restore:hover { background:rgba(255,171,46,.35); }
        .sg-x { cursor:pointer; padding:6px 13px; border-radius:8px; background:#e5383b; color:#fff; font-weight:800; font-size:14px; line-height:1; box-shadow:0 2px 8px rgba(0,0,0,.35); transition:filter .12s, transform .12s; }
        .sg-x:hover { filter:brightness(1.15); transform:scale(1.06); }
        .sg-scroll { flex:1; overflow:auto; padding:20px 24px 110px; }

        .sg-scroll > .sg-grid + .sg-grid { margin-top:30px; }
        .sg-grid { display:flex; flex-wrap:wrap; align-items:flex-start; gap:18px 14px; }

        .sg-tile { width:calc(var(--sg-size) + 20px); cursor:pointer; text-align:center; border-radius:14px; padding:2px 0; }
        .sg-icon {
            position:relative; width:var(--sg-size); height:var(--sg-size); margin:0 auto;
            border-radius:calc(var(--sg-size) / 2);
            background:#2b2d31;
            display:flex; align-items:center; justify-content:center;
            transition:border-radius .15s, transform .15s;
        }
        .sg-icon > img { width:100%; height:100%; object-fit:cover; border-radius:inherit; }
        .sg-tile:hover .sg-icon { border-radius:16px; transform:translateY(-2px); }
        .sg-tile.current .sg-icon { border-radius:16px; box-shadow:0 0 0 3px #ffab2e; }
        .sg-tile { cursor:grab; touch-action:none; }
        .sg-tile.dragging { opacity:.3; }
        .sg-ghost { position:absolute; z-index:60; pointer-events:none; opacity:.9; transform:scale(1.1); cursor:grabbing; }
        .sg-tile { position:relative; }
        .sg-tile.drop-before::before, .sg-tile.drop-after::after {
            content:""; position:absolute; top:-2px; bottom:-2px; width:4px; border-radius:2px;
            background:#ffab2e; box-shadow:0 0 8px #ffab2e; z-index:8;
        }
        .sg-tile.drop-before::before { left:-9px; }
        .sg-tile.drop-after::after { right:-9px; }
        .sg-tile.axis-y.drop-before::before, .sg-tile.axis-y.drop-after::after { top:auto; bottom:auto; left:0; right:0; width:auto; height:4px; }
        .sg-tile.axis-y.drop-before::before { top:-7px; }
        .sg-tile.drop-into { background:rgba(255,171,46,.22); outline:2px dashed #ffab2e; }
        .sg-tile.drop-into .sg-icon { transform:scale(1.08); border-radius:18px; }
        .sg-scroll.drop-bg { box-shadow:inset 0 0 0 3px rgba(255,171,46,.6); }
        .sg-input { width:100%; padding:9px 12px; margin-bottom:16px; border-radius:8px; border:1px solid rgba(255,255,255,.25); background:#120a22; color:#fff; font-size:14px; outline:none; user-select:text; }
        .sg-input:focus { border-color:#ffab2e; }
        .sg-btn.primary { background:#ff9f1a; color:#2a1000; }
        .sg-tile.axis-y.drop-after::after { bottom:-7px; }
        .sg-acro { font-weight:700; font-size:calc(var(--sg-size) / 3); }
        .sg-name { margin-top:6px; font-size:11px; line-height:1.2; opacity:.85; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

        .sg-badge {
            position:absolute; right:-4px; bottom:-4px; min-width:18px; height:18px; padding:0 5px;
            border-radius:9px; background:#f23f42; color:#fff; font-size:11px; font-weight:700;
            display:flex; align-items:center; justify-content:center; border:2px solid #4a1f8c;
        }
        .sg-dot { position:absolute; left:-6px; top:50%; width:8px; height:8px; margin-top:-4px; border-radius:50%; background:#fff; }

        .sg-folder { border:2px solid transparent; border-radius:18px; padding:4px 4px 8px; }
        .sg-folder.open { background:rgba(255,255,255,.1); }
        .sg-folder-icon { border:2px solid; border-radius:18px !important; }
        .sg-mini { display:grid; grid-template-columns:1fr 1fr; gap:3px; width:70%; height:70%; }
        .sg-mini img, .sg-mini-acro { width:100%; height:100%; object-fit:cover; border-radius:50%; font-size:10px; display:flex; align-items:center; justify-content:center; background:rgba(255,255,255,.1); }

        .sg-panel { display:grid; grid-auto-flow:column; gap:12px 8px; padding:14px 6px 4px; }

        /* mascot, bottom left (behind the content, transparent background) */
        .sg-logo {
            position:absolute; left:12px; bottom:0; z-index:0;
            width:256px; height:256px; pointer-events:none;
            background:url("${MASCOT}") center/contain no-repeat;
        }
        .sg-view { z-index:1; }

        /* bottom right buttons */
        .sg-actions { position:absolute; right:28px; bottom:24px; z-index:5; display:flex; gap:12px; }
        .sg-actionbtn {
            padding:12px 26px; border-radius:12px; cursor:pointer;
            font-size:15px; font-weight:800; white-space:nowrap;
            box-shadow:0 4px 14px rgba(0,0,0,.45);
            transition:transform .12s, filter .12s;
        }
        .sg-actionbtn:hover { transform:translateY(-2px); filter:brightness(1.08); }
        .sg-openbtn { color:#3a0023; background:linear-gradient(135deg,#ff8fcb,#ff5fb0); }
        .sg-closebtn { color:#2a1000; background:linear-gradient(135deg,#ffb429,#ff8a1a); }

        /* right-click menu */
        .sg-menu { position:absolute; z-index:20; width:230px; padding:6px; border-radius:10px; background:#1f1033; box-shadow:0 8px 24px rgba(0,0,0,.6); border:1px solid rgba(255,255,255,.12); }
        .sg-menu-title { padding:6px 10px; font-size:11px; opacity:.6; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
        .sg-menu-item { padding:8px 10px; border-radius:6px; font-size:13px; cursor:pointer; }
        .sg-menu-item:hover { background:#5b2ea8; }
        .sg-menu-item.danger { color:#ff6b6e; }
        .sg-menu-item.danger:hover { background:#f23f42; color:#fff; }
        .sg-menu-sep { height:1px; margin:4px 6px; background:rgba(255,255,255,.12); }

        /* dialogs */
        .sg-modal { position:absolute; inset:0; z-index:30; background:rgba(10,0,25,.65); display:flex; align-items:center; justify-content:center; }
        .sg-modal-box { width:min(420px, 90%); padding:22px; border-radius:14px; background:#1f1033; border:1px solid rgba(255,255,255,.15); box-shadow:0 12px 40px rgba(0,0,0,.6); }
        .sg-modal-title { font-size:18px; font-weight:800; margin-bottom:10px; }
        .sg-modal-text { font-size:14px; opacity:.8; line-height:1.4; margin-bottom:18px; }
        .sg-modal-actions { display:flex; justify-content:flex-end; gap:10px; }
        .sg-btn { padding:8px 18px; border-radius:8px; cursor:pointer; font-size:14px; font-weight:700; background:rgba(255,255,255,.12); }
        .sg-btn:hover { background:rgba(255,255,255,.2); }
        .sg-btn.danger { background:#f23f42; }
        .sg-btn.danger:hover { background:#d83639; }

        .sg-toast { max-width:80%; line-height:1.4; cursor:pointer; user-select:text; position:absolute; left:50%; bottom:90px; transform:translateX(-50%); z-index:40; padding:10px 18px; border-radius:10px; background:#1f1033; border:1px solid rgba(255,255,255,.15); font-size:13px; box-shadow:0 6px 20px rgba(0,0,0,.5); }
        `;
    }
};
